// Package data contains data and information about the data files.
package data

import "time"

// ShortNewsRecording is a JSON file generated by using
// `app.ExportRecordingData()` in recorderapp package.
const (
	ShortNewsRecording         = "short_news_recording.json"
	ShortNewsRecordingDuration = 208390 * time.Millisecond
)

// ShortNewsAudio is an audio file generated by
// gtts-cli -f news.txt --output=short_news.mp3
// ffmpeg -i short_news.mp3 short_news.wav
const (
	ShortNewsAudio         = "short_news.wav"
	ShortNewsAudioDuration = 33940 * time.Millisecond
)
